const C = {
  bg: '#F6F4EE',
  surface: '#FFFFFF',
  ink: '#1E241F',
  inkMuted: '#767D70',
  inkFaint: '#A6AB9C',
  border: '#E4E0D3',
  accent: '#124F9F',
  accentSoft: '#E7EEF8',
  gold: '#E69A09',
  goldSoft: '#FBF0DC',
  pendiente: '#AD7A0A',
  pendienteSoft: '#FBF0DC',
  completo: '#1F8A5F',
  completoSoft: '#E6F4EC',
  parcial: '#BE4B22',
  parcialSoft: '#FAEAE0',
  cancelado: '#8B8676',
  canceladoSoft: '#EDEAE0',
  especial: '#6E5AA0',
  especialSoft: '#EFEAF6',
};

function uid(prefix) {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
}

function formatFecha(iso) {
  if (!iso) return '';
  try {
    return new Date(iso).toLocaleString('es-MX', {
      day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit',
    });
  } catch {
    return iso;
  }
}

function estadoDe(pedido) {
  if (pedido.estado !== 'entregado') return pedido.estado;
  const completo = pedido.productos.every(
    (p) => p.entregado && Number(p.cantidad_entregada) >= Number(p.cantidad)
  );
  return completo ? 'completo' : 'parcial';
}

const ESTADO_META = {
  pendiente: { label: 'Pendiente', color: C.pendiente, bg: C.pendienteSoft, Icon: Clock },
  completo: { label: 'Entregado', color: C.completo, bg: C.completoSoft, Icon: CheckCircle2 },
  parcial: { label: 'Entregado parcial', color: C.parcial, bg: C.parcialSoft, Icon: AlertCircle },
  cancelado: { label: 'Cancelado', color: C.cancelado, bg: C.canceladoSoft, Icon: X },
};

function Pill({ estado }) {
  const meta = ESTADO_META[estado] || ESTADO_META.pendiente;
  const { Icon } = meta;
  return (
    <span
      className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold shrink-0"
      style={{ background: meta.bg, color: meta.color }}
    >
      <Icon size={13} strokeWidth={2.5} />
      {meta.label}
    </span>
  );
}

function EspecialTag() {
  return (
    <span
      className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-wide shrink-0"
      style={{ background: C.especialSoft, color: C.especial }}
    >
      <Sparkles size={10} /> Especial
    </span>
  );
}

function TopBar({ title, subtitle, onBack, right }) {
  return (
    <div className="flex items-start justify-between gap-3 mb-5">
      <div className="flex items-start gap-2">
        {onBack && (
          <button
            onClick={onBack}
            className="mt-0.5 shrink-0 rounded-full p-1.5 hover:bg-black/5 active:scale-95 transition"
            style={{ color: C.ink }}
          >
            <ChevronLeft size={20} />
          </button>
        )}
        <div>
          <h1 className="text-lg font-bold leading-tight" style={{ color: C.ink }}>{title}</h1>
          {subtitle && <p className="text-sm mt-0.5" style={{ color: C.inkMuted }}>{subtitle}</p>}
        </div>
      </div>
      {right}
    </div>
  );
}

function EmptyState({ Icon, title, sub }) {
  return (
    <div className="flex flex-col items-center text-center py-14 px-6 rounded-2xl border border-dashed" style={{ borderColor: C.border }}>
      <div className="rounded-full p-3 mb-3" style={{ background: C.accentSoft }}>
        <Icon size={22} style={{ color: C.accent }} />
      </div>
      <p className="font-semibold text-sm" style={{ color: C.ink }}>{title}</p>
      {sub && <p className="text-xs mt-1 max-w-[220px]" style={{ color: C.inkMuted }}>{sub}</p>}
    </div>
  );
}

function Stamp({ active, onClick }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="shrink-0 rounded-full flex items-center justify-center transition-all duration-150"
      style={{
        width: 34, height: 34,
        border: `2px solid ${active ? C.completo : C.border}`,
        background: active ? C.completoSoft : 'transparent',
        transform: active ? 'rotate(-4deg)' : 'none',
      }}
    >
      <Check size={16} strokeWidth={3} style={{ color: active ? C.completo : C.inkFaint }} />
    </button>
  );
}

function CodeField({ value, onChange, placeholder, onEnter }) {
  const [show, setShow] = useState(false);
  return (
    <div className="relative">
      <input
        type={show ? 'text' : 'password'}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={(e) => { if (e.key === 'Enter' && onEnter) onEnter(); }}
        placeholder={placeholder}
        className="w-full text-sm rounded-lg pl-3 pr-10 py-2.5 outline-none border tracking-wide"
        style={{ borderColor: C.border, color: C.ink }}
        autoFocus
      />
      <button
        type="button"
        onClick={() => setShow((s) => !s)}
        className="absolute right-2.5 top-1/2 -translate-y-1/2 p-1 rounded hover:bg-black/5"
      >
        {show ? <EyeOff size={15} style={{ color: C.inkFaint }} /> : <Eye size={15} style={{ color: C.inkFaint }} />}
      </button>
    </div>
  );
}

