// ---------- Código personal ----------

function CodigoScreen({ preRole, empleados, onBack, onSuccess }) {
  const [codigo, setCodigo] = useState('');
  const [error, setError] = useState('');

  const submit = () => {
    const val = codigo.trim();
    if (!val) return;
    const emp = empleados.find(
      (e) =>
        e.codigo.toUpperCase() === val.toUpperCase() &&
        e.area === preRole.type &&
        (preRole.type !== 'sucursal' || e.sucursal === preRole.nombre)
    );
    if (emp) {
      setError('');
      onSuccess(emp);
    } else {
      setError('Código incorrecto. Verifica con el administrador.');
    }
  };

  const sinEmpleados = empleados.filter(
    (e) => e.area === preRole.type && (preRole.type !== 'sucursal' || e.sucursal === preRole.nombre)
  ).length === 0;

  return (
    <div>
      <TopBar title={preRole.type === 'sucursal' ? preRole.nombre : 'Compras'} subtitle="Ingresa tu código personal" onBack={onBack} />

      <CodeField value={codigo} onChange={setCodigo} placeholder="Tu código" onEnter={submit} />

      {error && <p className="text-xs mt-2 font-medium" style={{ color: C.parcial }}>{error}</p>}
      {sinEmpleados && (
        <p className="text-xs mt-2" style={{ color: C.inkFaint }}>
          Aún no hay códigos registrados aquí. Pide al administrador que los dé de alta en Administración.
        </p>
      )}

      <button
        onClick={submit}
        className="w-full mt-4 py-3 rounded-xl font-semibold text-sm text-white"
        style={{ background: C.accent }}
      >
        Entrar
      </button>
    </div>
  );
}

// ---------- Administración: gate ----------

function AdminGateScreen({ onBack, onSuccess }) {
  const [codigo, setCodigo] = useState('');
  const [error, setError] = useState('');

  const submit = () => {
    if (codigo.trim() === ADMIN_CODE) { setError(''); onSuccess(); }
    else setError('Código de administrador incorrecto.');
  };

  return (
    <div>
      <TopBar title="Administración" subtitle="Acceso restringido" onBack={onBack} />
      <div className="flex items-center gap-2 mb-4 p-3 rounded-xl" style={{ background: C.accentSoft }}>
        <ShieldCheck size={16} style={{ color: C.accent }} />
        <p className="text-xs" style={{ color: C.accent }}>Aquí se dan de alta empleados, sus códigos y el catálogo.</p>
      </div>
      <CodeField value={codigo} onChange={setCodigo} placeholder="Código de administrador" onEnter={submit} />
      {error && <p className="text-xs mt-2 font-medium" style={{ color: C.parcial }}>{error}</p>}
      <button onClick={submit} className="w-full mt-4 py-3 rounded-xl font-semibold text-sm text-white" style={{ background: C.accent }}>
        Entrar
      </button>
    </div>
  );
}

// ---------- Administración: empleados ----------

function EmpleadosAdmin({ empleados, onAdd, onDelete, saving }) {
  const [nombre, setNombre] = useState('');
  const [area, setArea] = useState('sucursal');
  const [sucursal, setSucursal] = useState(SUCURSALES[0]);
  const [codigo, setCodigo] = useState('');
  const [error, setError] = useState('');

  const submit = () => {
    if (!nombre.trim() || !codigo.trim()) return;
    const dup = empleados.some((e) => e.codigo.toUpperCase() === codigo.trim().toUpperCase());
    if (dup) { setError('Ese código ya está en uso por otro empleado.'); return; }
    onAdd(nombre.trim(), area, area === 'sucursal' ? sucursal : null, codigo.trim());
    setNombre(''); setCodigo(''); setError('');
  };

  const ordenados = useMemo(() => [...empleados].sort((a, b) => a.nombre.localeCompare(b.nombre)), [empleados]);

  return (
    <div>
      <div className="p-3.5 rounded-xl border mb-5" style={{ borderColor: C.border, background: C.surface }}>
        <p className="text-xs font-bold uppercase tracking-wide mb-2.5" style={{ color: C.inkFaint }}>Dar de alta empleado</p>
        <input
          value={nombre}
          onChange={(e) => setNombre(e.target.value)}
          placeholder="Nombre completo"
          className="w-full text-sm rounded-lg px-3 py-2 mb-2 outline-none border"
          style={{ borderColor: C.border, color: C.ink }}
        />
        <div className="flex gap-2 mb-2">
          {['sucursal', 'compras'].map((a) => (
            <button
              key={a}
              onClick={() => setArea(a)}
              className="flex-1 py-2 rounded-lg text-xs font-bold border"
              style={{
                borderColor: area === a ? C.accent : C.border,
                background: area === a ? C.accentSoft : 'transparent',
                color: area === a ? C.accent : C.inkMuted,
              }}
            >
              {a === 'sucursal' ? 'Sucursal' : 'Compras'}
            </button>
          ))}
        </div>
        {area === 'sucursal' && (
          <select
            value={sucursal}
            onChange={(e) => setSucursal(e.target.value)}
            className="w-full text-sm rounded-lg px-3 py-2 mb-2 outline-none border"
            style={{ borderColor: C.border, color: C.ink }}
          >
            {SUCURSALES.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        )}
        <input
          value={codigo}
          onChange={(e) => setCodigo(e.target.value)}
          placeholder="Código que usará para entrar"
          className="w-full text-sm rounded-lg px-3 py-2 mb-2 outline-none border tracking-wide"
          style={{ borderColor: C.border, color: C.ink }}
        />
        {error && <p className="text-xs mb-2 font-medium" style={{ color: C.parcial }}>{error}</p>}
        <button
          disabled={!nombre.trim() || !codigo.trim() || saving}
          onClick={submit}
          className="w-full py-2.5 rounded-lg text-sm font-semibold text-white disabled:opacity-40"
          style={{ background: C.accent }}
        >
          Agregar empleado
        </button>
      </div>

      <p className="text-xs font-bold uppercase tracking-wide mb-2" style={{ color: C.inkFaint }}>
        {empleados.length} empleado{empleados.length !== 1 ? 's' : ''} dado{empleados.length !== 1 ? 's' : ''} de alta
      </p>

      {ordenados.length === 0 ? (
        <EmptyState Icon={Users} title="Sin empleados" sub="Agrega a cada persona con el código que va a usar para entrar." />
      ) : (
        <div className="rounded-xl border overflow-hidden" style={{ borderColor: C.border, background: C.surface }}>
          {ordenados.map((e, i) => (
            <div key={e.id} className="flex items-center justify-between px-3.5 py-2.5" style={{ borderTop: i > 0 ? `1px solid ${C.border}` : 'none' }}>
              <div className="min-w-0">
                <p className="text-sm font-medium truncate" style={{ color: C.ink }}>{e.nombre}</p>
                <p className="text-xs" style={{ color: C.inkMuted }}>
                  {e.area === 'compras' ? 'Compras' : e.sucursal} · <span className="tracking-wide">{e.codigo}</span>
                </p>
              </div>
              <button onClick={() => onDelete(e.id)} className="p-1.5 rounded hover:bg-black/5 shrink-0">
                <Trash2 size={14} style={{ color: C.inkMuted }} />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

