// ---------- Nuevo pedido: fila de catálogo ----------

function CatalogRow({ row, catalogo, onSelect, onChangeCantidad, onClear, onRemove }) {
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);

  const matches = useMemo(() => {
    if (!query.trim()) return [];
    return catalogo.filter((c) => c.nombre.toLowerCase().includes(query.toLowerCase())).slice(0, 6);
  }, [query, catalogo]);

  return (
    <div className="p-3 rounded-xl border" style={{ borderColor: C.border, background: C.surface }}>
      <div className="flex items-center justify-between mb-2">
        <span className="text-[10px] font-bold uppercase tracking-wide px-2 py-0.5 rounded-md" style={{ background: C.accentSoft, color: C.accent }}>Del catálogo</span>
        <button onClick={() => onRemove(row.id)} className="p-1 rounded hover:bg-black/5">
          <Trash2 size={14} style={{ color: C.inkMuted }} />
        </button>
      </div>

      {row.catalogId ? (
        <div className="flex items-center justify-between gap-2 mb-2">
          <div className="min-w-0">
            <p className="text-sm font-medium truncate" style={{ color: C.ink }}>{row.nombre}</p>
            <p className="text-xs" style={{ color: C.inkMuted }}>{row.unidad}</p>
          </div>
          <button onClick={onClear} className="text-xs font-semibold shrink-0" style={{ color: C.accent }}>Cambiar</button>
        </div>
      ) : (
        <div className="relative mb-2">
          <input
            value={query}
            onChange={(e) => { setQuery(e.target.value); setOpen(true); }}
            onFocus={() => setOpen(true)}
            placeholder="Buscar producto del catálogo…"
            className="w-full text-sm rounded-lg px-3 py-2 outline-none border"
            style={{ borderColor: C.border, color: C.ink }}
          />
          {open && query.trim() && (
            <div className="absolute z-10 left-0 right-0 mt-1 rounded-lg border shadow-sm max-h-48 overflow-auto" style={{ borderColor: C.border, background: C.surface }}>
              {matches.length === 0 ? (
                <p className="text-xs px-3 py-2.5" style={{ color: C.inkMuted }}>
                  No aparece en el catálogo. Si es algo nuevo para un cliente, quita esta línea y usa "Producto especial".
                </p>
              ) : (
                matches.map((m) => (
                  <button
                    key={m.id}
                    onClick={() => { onSelect(row.id, m); setOpen(false); setQuery(''); }}
                    className="w-full text-left px-3 py-2 text-sm hover:bg-black/[0.03]"
                    style={{ color: C.ink }}
                  >
                    {m.nombre} <span style={{ color: C.inkFaint }}>· {m.unidad}</span>
                  </button>
                ))
              )}
            </div>
          )}
        </div>
      )}

      <input
        type="number"
        min="0"
        disabled={!row.catalogId}
        value={row.cantidad}
        onChange={(e) => onChangeCantidad(row.id, e.target.value)}
        placeholder="Cantidad"
        className="w-1/2 text-sm rounded-lg px-3 py-2 outline-none border disabled:opacity-40"
        style={{ borderColor: C.border, color: C.ink }}
      />
    </div>
  );
}

