// ---------- Sucursal: nuevo pedido ----------

function NuevoPedido({ sucursal, catalogo, onCancel, onCreate, saving }) {
  const [rows, setRows] = useState([]);

  const addCatalogo = () => setRows((rs) => [...rs, { id: uid('r'), tipo: 'catalogo', nombre: '', unidad: '', cantidad: '', catalogId: null }]);
  const addEspecial = () => setRows((rs) => [...rs, { id: uid('r'), tipo: 'especial', nombre: '', unidad: '', cantidad: '', cliente: '' }]);
  const removeRow = (id) => setRows((rs) => rs.filter((r) => r.id !== id));

  const selectCatalogItem = (id, item) =>
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, nombre: item.nombre, unidad: item.unidad, catalogId: item.id } : r)));
  const clearCatalog = (id) =>
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, nombre: '', unidad: '', catalogId: null, cantidad: '' } : r)));
  const changeCantidadCatalogo = (id, val) =>
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, cantidad: val } : r)));
  const changeEspecial = (id, field, val) =>
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, [field]: val } : r)));

  const validRows = rows.filter((r) =>
    r.tipo === 'catalogo' ? (r.catalogId && Number(r.cantidad) > 0) : (r.nombre.trim() && Number(r.cantidad) > 0)
  );
  const canSubmit = validRows.length > 0 && !saving;

  const buildPayload = () =>
    validRows.map((r) =>
      r.tipo === 'catalogo'
        ? { tipo: 'catalogo', nombre: r.nombre, unidad: r.unidad, cantidad: Number(r.cantidad), catalogId: r.catalogId }
        : { tipo: 'especial', nombre: r.nombre.trim(), unidad: r.unidad.trim() || 'pza', cantidad: Number(r.cantidad), cliente: r.cliente.trim() }
    );

  return (
    <div>
      <TopBar title="Nuevo pedido" subtitle={sucursal} onBack={onCancel} />

      {rows.length === 0 && (
        <div className="mb-3">
          <EmptyState Icon={ClipboardList} title="Agrega tu primer producto" sub="Del catálogo, o especial si es algo nuevo para un cliente." />
        </div>
      )}

      <div className="space-y-2.5 mb-3">
        {rows.map((r) =>
          r.tipo === 'catalogo' ? (
            <CatalogRow
              key={r.id}
              row={r}
              catalogo={catalogo}
              onSelect={selectCatalogItem}
              onChangeCantidad={changeCantidadCatalogo}
              onClear={() => clearCatalog(r.id)}
              onRemove={removeRow}
            />
          ) : (
            <EspecialRow key={r.id} row={r} onChange={changeEspecial} onRemove={removeRow} />
          )
        )}
      </div>

      <div className="flex gap-2 mb-5">
        <button
          onClick={addCatalogo}
          className="flex-1 flex items-center justify-center gap-1.5 py-2.5 rounded-xl border border-dashed text-sm font-semibold"
          style={{ borderColor: C.border, color: C.accent }}
        >
          <Plus size={16} /> Del catálogo
        </button>
        <button
          onClick={addEspecial}
          className="flex-1 flex items-center justify-center gap-1.5 py-2.5 rounded-xl border border-dashed text-sm font-semibold"
          style={{ borderColor: C.especial, color: C.especial }}
        >
          <Plus size={16} /> Producto especial
        </button>
      </div>

      <button
        disabled={!canSubmit}
        onClick={() => onCreate(buildPayload())}
        className="w-full py-3 rounded-xl font-semibold text-sm text-white transition disabled:opacity-40"
        style={{ background: C.accent }}
      >
        {saving ? 'Guardando…' : `Levantar pedido${validRows.length ? ` (${validRows.length})` : ''}`}
      </button>
    </div>
  );
}

// ---------- Detalle (lectura) ----------

function DetallePedido({ pedido, onBack, onCancelar }) {
  const estado = estadoDe(pedido);
  const entregado = pedido.estado === 'entregado';

  return (
    <div>
      <TopBar
        title={pedido.sucursal}
        subtitle={`${formatFecha(pedido.fecha_creacion)}${pedido.creado_por ? ' · ' + pedido.creado_por : ''}`}
        onBack={onBack}
      />

      <div className="mb-4"><Pill estado={estado} /></div>

      <div className="rounded-xl border overflow-hidden mb-4" style={{ borderColor: C.border, background: C.surface }}>
        {pedido.productos.map((p, i) => (
          <div
            key={p.id}
            className="flex items-center justify-between px-3.5 py-3 text-sm"
            style={{ borderTop: i > 0 ? `1px solid ${C.border}` : 'none' }}
          >
            <div className="min-w-0">
              <div className="flex items-center gap-1.5 flex-wrap">
                <p className="font-medium truncate" style={{ color: C.ink }}>{p.nombre}</p>
                {p.tipo === 'especial' && <EspecialTag />}
              </div>
              {p.cliente && <p className="text-xs mt-0.5" style={{ color: C.especial }}>Para: {p.cliente}</p>}
              <p className="text-xs mt-0.5" style={{ color: C.inkMuted }}>
                Pedido: {p.cantidad} {p.unidad}
                {entregado && (
                  <>
                    {' · '}
                    <span style={{ color: Number(p.cantidad_entregada) >= Number(p.cantidad) && p.entregado ? C.completo : C.parcial, fontWeight: 600 }}>
                      Entregado: {p.entregado ? `${p.cantidad_entregada} ${p.unidad}` : '0'}
                    </span>
                  </>
                )}
              </p>
              {p.nota && <p className="text-xs italic mt-0.5" style={{ color: C.inkFaint }}>Nota: {p.nota}</p>}
            </div>
            {entregado && (
              p.entregado && Number(p.cantidad_entregada) >= Number(p.cantidad)
                ? <CheckCircle2 size={18} style={{ color: C.completo }} className="shrink-0 ml-2" />
                : <AlertCircle size={18} style={{ color: C.parcial }} className="shrink-0 ml-2" />
            )}
          </div>
        ))}
      </div>

      {entregado && (
        <div className="rounded-xl border p-4 mb-4" style={{ borderColor: C.border, background: C.surface }}>
          <p className="text-xs font-bold uppercase tracking-wide mb-3" style={{ color: C.inkFaint }}>Firmas de entrega</p>
          <div className="flex justify-between gap-4 mb-3">
            <div className="flex-1">
              <p className="text-[11px]" style={{ color: C.inkMuted }}>Entregó (compras)</p>
              <p className="text-sm font-semibold italic pb-1 border-b" style={{ color: C.ink, borderColor: C.border }}>{pedido.entregado_por || '—'}</p>
            </div>
            <div className="flex-1">
              <p className="text-[11px]" style={{ color: C.inkMuted }}>Recibió (sucursal)</p>
              <p className="text-sm font-semibold italic pb-1 border-b" style={{ color: C.ink, borderColor: C.border }}>{pedido.recibido_por || '—'}</p>
            </div>
          </div>
          <p className="text-xs" style={{ color: C.inkFaint }}>Entregado el {formatFecha(pedido.fecha_entrega)}</p>
        </div>
      )}

      {pedido.estado === 'pendiente' && onCancelar && (
        <button
          onClick={onCancelar}
          className="w-full py-2.5 rounded-xl border text-sm font-semibold"
          style={{ borderColor: C.parcial, color: C.parcial }}
        >
          Cancelar pedido
        </button>
      )}
    </div>
  );
}

// ---------- Sucursal: lista ----------

function VistaSucursal({ sucursal, pedidos, onNuevo, onOpen, refreshing }) {
  const mios = useMemo(
    () => pedidos.filter((p) => p.sucursal === sucursal).sort((a, b) => new Date(b.fecha_creacion) - new Date(a.fecha_creacion)),
    [pedidos, sucursal]
  );

  return (
    <div>
      <button
        onClick={onNuevo}
        className="w-full flex items-center justify-center gap-1.5 py-3 rounded-xl font-semibold text-sm text-white mb-5"
        style={{ background: C.accent }}
      >
        <Plus size={17} /> Nuevo pedido
      </button>

      <div className="flex items-center justify-between mb-2.5">
        <p className="text-xs font-bold uppercase tracking-wide" style={{ color: C.inkFaint }}>Mis pedidos</p>
        {refreshing && <RefreshCw size={12} className="animate-spin" style={{ color: C.inkFaint }} />}
      </div>

      {mios.length === 0 ? (
        <EmptyState Icon={ClipboardList} title="Sin pedidos todavía" sub="Levanta tu primer pedido para que compras lo surta." />
      ) : (
        <div className="space-y-2">
          {mios.map((p) => {
            const estado = estadoDe(p);
            const meta = ESTADO_META[estado];
            const tieneEspecial = p.productos.some((x) => x.tipo === 'especial');
            return (
              <button
                key={p.id}
                onClick={() => onOpen(p.id)}
                className="w-full flex items-center justify-between gap-3 p-3.5 rounded-xl border text-left active:scale-[0.99] transition"
                style={{ borderColor: C.border, background: C.surface, borderLeft: `4px solid ${meta.color}` }}
              >
                <div className="min-w-0">
                  <div className="flex items-center gap-1.5">
                    <p className="font-semibold text-sm" style={{ color: C.ink }}>{p.productos.length} producto{p.productos.length !== 1 ? 's' : ''}</p>
                    {tieneEspecial && <EspecialTag />}
                  </div>
                  <p className="text-xs mt-0.5" style={{ color: C.inkMuted }}>
                    {formatFecha(p.fecha_creacion)}{p.creado_por ? ` · ${p.creado_por}` : ''}
                  </p>
                </div>
                <div className="flex items-center gap-1.5 shrink-0">
                  <Pill estado={estado} />
                  <ChevronRight size={16} style={{ color: C.inkFaint }} />
                </div>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ---------- Compras: cola de pendientes ----------

function VistaComprasCola({ pendientes, onAbrir, refreshing }) {
  return (
    <div>
      <div className="flex items-center justify-between mb-2.5">
        <p className="text-xs font-bold uppercase tracking-wide" style={{ color: C.inkFaint }}>
          Pedidos por surtir {pendientes.length > 0 && `(${pendientes.length})`}
        </p>
        {refreshing && <RefreshCw size={12} className="animate-spin" style={{ color: C.inkFaint }} />}
      </div>

      {pendientes.length === 0 ? (
        <EmptyState Icon={Package} title="No hay pedidos pendientes" sub="Cuando una sucursal levante un pedido, aparecerá aquí." />
      ) : (
        <div className="space-y-2">
          {pendientes.map((p) => {
            const tieneEspecial = p.productos.some((x) => x.tipo === 'especial');
            return (
              <button
                key={p.id}
                onClick={() => onAbrir(p.id)}
                className="w-full flex items-center justify-between gap-3 p-3.5 rounded-xl border text-left active:scale-[0.99] transition"
                style={{ borderColor: C.border, background: C.surface, borderLeft: `4px solid ${C.pendiente}` }}
              >
                <div className="min-w-0">
                  <div className="flex items-center gap-1.5">
                    <p className="font-semibold text-sm" style={{ color: C.ink }}>{p.sucursal}</p>
                    {tieneEspecial && <EspecialTag />}
                  </div>
                  <p className="text-xs mt-0.5" style={{ color: C.inkMuted }}>
                    {p.productos.length} producto{p.productos.length !== 1 ? 's' : ''} · {formatFecha(p.fecha_creacion)}
                  </p>
                </div>
                <ChevronRight size={16} style={{ color: C.inkFaint }} className="shrink-0" />
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ---------- Compras: checklist de entrega ----------

function VistaEntrega({ pedido, role, empleados, onBack, onConfirmar, saving }) {
  const [items, setItems] = useState(() =>
    pedido.productos.map((p) => ({
      ...p,
      entregado: p.entregado ?? true,
      cantidad_entregada: p.cantidad_entregada ?? p.cantidad,
      nota: p.nota ?? '',
    }))
  );
  const [codigoRecibe, setCodigoRecibe] = useState('');

  const toggle = (id) => setItems((its) => its.map((it) => (it.id === id ? { ...it, entregado: !it.entregado } : it)));
  const setCantidad = (id, val) => setItems((its) => its.map((it) => (it.id === id ? { ...it, cantidad_entregada: val } : it)));
  const setNota = (id, val) => setItems((its) => its.map((it) => (it.id === id ? { ...it, nota: val } : it)));

  const empleadoRecibe = useMemo(
    () => empleados.find((e) => e.codigo.toUpperCase() === codigoRecibe.trim().toUpperCase() && e.area === 'sucursal' && e.sucursal === pedido.sucursal),
    [codigoRecibe, empleados, pedido.sucursal]
  );
  const canConfirm = !!empleadoRecibe && !saving;

  return (
    <div>
      <TopBar title={`Surtir · ${pedido.sucursal}`} subtitle={formatFecha(pedido.fecha_creacion)} onBack={onBack} />

      <div className="rounded-xl border overflow-hidden mb-4" style={{ borderColor: C.border, background: C.surface }}>
        {items.map((it, i) => (
          <div key={it.id} className="flex items-start gap-3 px-3.5 py-3" style={{ borderTop: i > 0 ? `1px solid ${C.border}` : 'none' }}>
            <Stamp active={it.entregado} onClick={() => toggle(it.id)} />
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-1.5 flex-wrap mb-0.5">
                <p className="font-medium text-sm" style={{ color: C.ink }}>{it.nombre}</p>
                {it.tipo === 'especial' && <EspecialTag />}
              </div>
              {it.cliente && <p className="text-xs mb-1" style={{ color: C.especial }}>Para: {it.cliente}</p>}
              <p className="text-xs mb-2" style={{ color: C.inkMuted }}>Pedido: {it.cantidad} {it.unidad}</p>
              <div className="flex gap-2">
                <input
                  type="number"
                  min="0"
                  disabled={!it.entregado}
                  value={it.cantidad_entregada}
                  onChange={(e) => setCantidad(it.id, e.target.value)}
                  className="w-24 text-sm rounded-lg px-2.5 py-1.5 outline-none border disabled:opacity-40"
                  style={{ borderColor: C.border, color: C.ink }}
                />
                <input
                  placeholder="Nota (opcional)"
                  value={it.nota}
                  onChange={(e) => setNota(it.id, e.target.value)}
                  className="flex-1 text-sm rounded-lg px-2.5 py-1.5 outline-none border"
                  style={{ borderColor: C.border, color: C.ink }}
                />
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="rounded-xl border p-4 mb-5" style={{ borderColor: C.border, background: C.surface }}>
        <p className="text-xs font-bold uppercase tracking-wide mb-3" style={{ color: C.inkFaint }}>Firmar entrega</p>

        <p className="text-[11px] mb-1" style={{ color: C.inkMuted }}>Entregó</p>
        <p className="text-sm font-semibold italic pb-2 mb-3 border-b" style={{ color: C.ink, borderColor: C.border }}>{role.nombre}</p>

        <label className="block text-[11px] mb-1" style={{ color: C.inkMuted }}>Código de quien recibe (lo teclea la persona de la sucursal)</label>
        <CodeField value={codigoRecibe} onChange={setCodigoRecibe} placeholder="Código de quien recibe" />
        {codigoRecibe.trim().length > 0 && (
          empleadoRecibe ? (
            <p className="text-xs mt-1.5 font-medium" style={{ color: C.completo }}>✓ {empleadoRecibe.nombre}</p>
          ) : (
            <p className="text-xs mt-1.5 font-medium" style={{ color: C.parcial }}>Código no reconocido en {pedido.sucursal}.</p>
          )
        )}
      </div>

      <button
        disabled={!canConfirm}
        onClick={() => onConfirmar(items, role.nombre, empleadoRecibe.nombre)}
        className="w-full py-3 rounded-xl font-semibold text-sm text-white disabled:opacity-40"
        style={{ background: C.accent }}
      >
        {saving ? 'Guardando…' : 'Confirmar entrega'}
      </button>
    </div>
  );
}

// ---------- Compras: historial ----------

function VistaHistorial({ pedidos, onOpen }) {
  const [filtro, setFiltro] = useState('todas');
  const historial = useMemo(
    () =>
      pedidos
        .filter((p) => p.estado !== 'pendiente')
        .filter((p) => filtro === 'todas' || p.sucursal === filtro)
        .sort((a, b) => new Date(b.fecha_entrega || b.fecha_creacion) - new Date(a.fecha_entrega || a.fecha_creacion)),
    [pedidos, filtro]
  );

  return (
    <div>
      <div className="flex gap-1.5 mb-4 overflow-x-auto pb-1">
        {['todas', ...SUCURSALES].map((s) => (
          <button
            key={s}
            onClick={() => setFiltro(s)}
            className="shrink-0 px-3 py-1.5 rounded-full text-xs font-semibold border"
            style={{
              borderColor: filtro === s ? C.accent : C.border,
              background: filtro === s ? C.accentSoft : 'transparent',
              color: filtro === s ? C.accent : C.inkMuted,
            }}
          >
            {s === 'todas' ? 'Todas' : s}
          </button>
        ))}
      </div>

      {historial.length === 0 ? (
        <EmptyState Icon={ClipboardList} title="Sin historial" sub="Aquí aparecerán los pedidos ya entregados o cancelados." />
      ) : (
        <div className="space-y-2">
          {historial.map((p) => {
            const estado = estadoDe(p);
            const meta = ESTADO_META[estado];
            return (
              <button
                key={p.id}
                onClick={() => onOpen(p.id)}
                className="w-full flex items-center justify-between gap-3 p-3.5 rounded-xl border text-left active:scale-[0.99] transition"
                style={{ borderColor: C.border, background: C.surface, borderLeft: `4px solid ${meta.color}` }}
              >
                <div className="min-w-0">
                  <p className="font-semibold text-sm" style={{ color: C.ink }}>{p.sucursal}</p>
                  <p className="text-xs mt-0.5" style={{ color: C.inkMuted }}>
                    {p.productos.length} producto{p.productos.length !== 1 ? 's' : ''} · {formatFecha(p.fecha_entrega || p.fecha_creacion)}
                  </p>
                </div>
                <Pill estado={estado} />
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ---------- App ----------

export default function App() {
  const [mode, setMode] = useState('seleccion'); // seleccion | codigo | admin-gate | admin | app
  const [preRole, setPreRole] = useState(null);
  const [role, setRole] = useState(null);

  const [pedidos, setPedidos] = useState([]);
  const [catalogo, setCatalogo] = useState([]);
  const [empleados, setEmpleados] = useState([]);

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const [screen, setScreen] = useState('lista');
  const [previousScreen, setPreviousScreen] = useState('lista');
  const [activeId, setActiveId] = useState(null);
  const [comprasTab, setComprasTab] = useState('cola');

  const cargar = useCallback(async (silent) => {
    if (!silent) setLoading(true); else setRefreshing(true);
    try {
      const [resPedidos, resCatalogo, resEmpleados] = await Promise.all([
        window.storage.get(PEDIDOS_KEY, true).catch(() => null),
        window.storage.get(CATALOGO_KEY, true).catch(() => null),
        window.storage.get(EMPLEADOS_KEY, true).catch(() => null),
      ]);
      setPedidos(resPedidos ? JSON.parse(resPedidos.value) : []);
      if (resCatalogo) {
        setCatalogo(JSON.parse(resCatalogo.value));
      } else {
        setCatalogo(CATALOGO_INICIAL);
        window.storage.set(CATALOGO_KEY, JSON.stringify(CATALOGO_INICIAL), true).catch(() => {});
      }
      if (resEmpleados) {
        setEmpleados(JSON.parse(resEmpleados.value));
      } else {
        setEmpleados(EMPLEADOS_INICIAL);
        window.storage.set(EMPLEADOS_KEY, JSON.stringify(EMPLEADOS_INICIAL), true).catch(() => {});
      }
      setError('');
    } catch (e) {
      // keep previous state on unexpected error
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  const guardarPedidos = useCallback(async (nuevos) => {
    setPedidos(nuevos);
    try {
      const res = await window.storage.set(PEDIDOS_KEY, JSON.stringify(nuevos), true);
      if (!res) setError('No se pudo guardar. Intenta de nuevo.');
    } catch {
      setError('No se pudo guardar. Intenta de nuevo.');
    }
  }, []);

  const guardarCatalogo = useCallback(async (nuevo) => {
    setCatalogo(nuevo);
    try {
      const res = await window.storage.set(CATALOGO_KEY, JSON.stringify(nuevo), true);
      if (!res) setError('No se pudo guardar el catálogo.');
    } catch {
      setError('No se pudo guardar el catálogo.');
    }
  }, []);

  const guardarEmpleados = useCallback(async (nuevo) => {
    setEmpleados(nuevo);
    try {
      const res = await window.storage.set(EMPLEADOS_KEY, JSON.stringify(nuevo), true);
      if (!res) setError('No se pudo guardar el empleado.');
    } catch {
      setError('No se pudo guardar el empleado.');
    }
  }, []);

  useEffect(() => { cargar(false); }, [cargar]);

  useEffect(() => {
    if (mode !== 'app') return;
    const interval = setInterval(() => cargar(true), 8000);
    return () => clearInterval(interval);
  }, [mode, cargar]);

  const salir = () => {
    setRole(null); setPreRole(null); setMode('seleccion');
    setScreen('lista'); setActiveId(null); setComprasTab('cola');
  };

  const abrirCatalogo = () => { setPreviousScreen(screen); setScreen('catalogo'); };
  const salirCatalogo = () => setScreen(previousScreen);

  const agregarCatalogo = async (nombre, unidad) => {
    await guardarCatalogo([...catalogo, { id: uid('cat'), nombre, unidad }]);
  };
  const eliminarCatalogo = async (id) => {
    await guardarCatalogo(catalogo.filter((c) => c.id !== id));
  };

  const agregarEmpleado = async (nombre, area, sucursal, codigo) => {
    await guardarEmpleados([...empleados, { id: uid('emp'), nombre, area, sucursal, codigo }]);
  };
  const eliminarEmpleado = async (id) => {
    await guardarEmpleados(empleados.filter((e) => e.id !== id));
  };

  const crearPedido = async (productosRows) => {
    setSaving(true);
    const nuevo = {
      id: uid('PED'),
      sucursal: role.sucursal,
      fecha_creacion: new Date().toISOString(),
      creado_por: role.nombre,
      productos: productosRows.map((r) => ({ id: uid('p'), ...r })),
      estado: 'pendiente',
      entregado_por: null,
      recibido_por: null,
      fecha_entrega: null,
    };
    await guardarPedidos([nuevo, ...pedidos]);
    setSaving(false);
    setScreen('lista');
  };

  const cancelarPedido = async (id) => {
    const nuevos = pedidos.map((p) => (p.id === id ? { ...p, estado: 'cancelado', cancelado_por: role.nombre } : p));
    await guardarPedidos(nuevos);
    setScreen('lista');
  };

  const confirmarEntrega = async (items, entregadoPor, recibidoPor) => {
    setSaving(true);
    const nuevos = pedidos.map((p) =>
      p.id === activeId
        ? { ...p, productos: items, estado: 'entregado', entregado_por: entregadoPor, recibido_por: recibidoPor, fecha_entrega: new Date().toISOString() }
        : p
    );
    await guardarPedidos(nuevos);
    setSaving(false);
    setComprasTab('cola');
    setScreen('lista');
    setActiveId(null);
  };

  const pedidoActivo = pedidos.find((p) => p.id === activeId);

  if (mode === 'seleccion') {
    return (
      <Shell error={error}>
        <RoleSelector
          onSucursal={(nombre) => { setPreRole({ type: 'sucursal', nombre }); setMode('codigo'); }}
          onCompras={() => { setPreRole({ type: 'compras' }); setMode('codigo'); }}
          onAdmin={() => setMode('admin-gate')}
        />
      </Shell>
    );
  }

  if (mode === 'codigo') {
    return (
      <Shell error={error}>
        <CodigoScreen
          preRole={preRole}
          empleados={empleados}
          onBack={() => setMode('seleccion')}
          onSuccess={(emp) => {
            setRole({ type: emp.area, nombre: emp.nombre, sucursal: emp.sucursal, empleadoId: emp.id });
            setMode('app');
            setScreen('lista');
          }}
        />
      </Shell>
    );
  }

  if (mode === 'admin-gate') {
    return (
      <Shell error={error}>
        <AdminGateScreen onBack={() => setMode('seleccion')} onSuccess={() => setMode('admin')} />
      </Shell>
    );
  }

  if (mode === 'admin') {
    return (
      <Shell error={error}>
        <AdminPanel
          empleados={empleados}
          catalogo={catalogo}
          onAddEmpleado={agregarEmpleado}
          onDeleteEmpleado={eliminarEmpleado}
          onAddCatalogo={agregarCatalogo}
          onDeleteCatalogo={eliminarCatalogo}
          onBack={() => setMode('seleccion')}
          saving={saving}
        />
      </Shell>
    );
  }

  // mode === 'app'
  let content;
  if (loading) {
    content = <div className="py-20 text-center text-sm" style={{ color: C.inkMuted }}>Cargando…</div>;
  } else if (screen === 'catalogo') {
    content = <CatalogoBrowse catalogo={catalogo} onBack={salirCatalogo} />;
  } else if (role.type === 'sucursal') {
    if (screen === 'nuevo') {
      content = <NuevoPedido sucursal={role.sucursal} catalogo={catalogo} saving={saving} onCancel={() => setScreen('lista')} onCreate={crearPedido} />;
    } else if (screen === 'detalle' && pedidoActivo) {
      content = (
        <DetallePedido
          pedido={pedidoActivo}
          onBack={() => { setScreen('lista'); setActiveId(null); }}
          onCancelar={pedidoActivo.estado === 'pendiente' ? () => cancelarPedido(pedidoActivo.id) : null}
        />
      );
    } else {
      content = (
        <VistaSucursal
          sucursal={role.sucursal}
          pedidos={pedidos}
          refreshing={refreshing}
          onNuevo={() => setScreen('nuevo')}
          onOpen={(id) => { setActiveId(id); setScreen('detalle'); }}
        />
      );
    }
  } else {
    if (screen === 'entrega' && pedidoActivo) {
      content = (
        <VistaEntrega
          pedido={pedidoActivo}
          role={role}
          empleados={empleados}
          saving={saving}
          onBack={() => { setScreen('lista'); setActiveId(null); }}
          onConfirmar={confirmarEntrega}
        />
      );
    } else if (screen === 'detalle' && pedidoActivo) {
      content = <DetallePedido pedido={pedidoActivo} onBack={() => { setScreen('lista'); setActiveId(null); }} />;
    } else {
      content = (
        <div>
          <div className="flex gap-1.5 mb-5">
            {[['cola', 'Pendientes'], ['historial', 'Historial']].map(([key, label]) => (
              <button
                key={key}
                onClick={() => setComprasTab(key)}
                className="px-3.5 py-1.5 rounded-full text-xs font-bold border"
                style={{
                  borderColor: comprasTab === key ? C.accent : C.border,
                  background: comprasTab === key ? C.accent : 'transparent',
                  color: comprasTab === key ? '#fff' : C.inkMuted,
                }}
              >
                {label}
              </button>
            ))}
          </div>
          {comprasTab === 'cola' ? (
            <VistaComprasCola
              pendientes={pedidos.filter((p) => p.estado === 'pendiente').sort((a, b) => new Date(a.fecha_creacion) - new Date(b.fecha_creacion))}
              refreshing={refreshing}
              onAbrir={(id) => { setActiveId(id); setScreen('entrega'); }}
            />
          ) : (
            <VistaHistorial pedidos={pedidos} onOpen={(id) => { setActiveId(id); setScreen('detalle'); }} />
          )}
        </div>
      );
    }
  }

  return (
    <Shell error={error}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-1.5 text-xs font-bold" style={{ color: C.accent }}>
          {role.type === 'sucursal' ? <Store size={13} /> : <Truck size={13} />}
          {role.nombre} · {role.type === 'sucursal' ? role.sucursal : 'Compras'}
        </div>
        <div className="flex items-center gap-3">
          <button onClick={abrirCatalogo} className="text-xs font-semibold underline" style={{ color: C.inkMuted }}>
            Catálogo
          </button>
          <button onClick={salir} className="text-xs font-semibold underline" style={{ color: C.inkMuted }}>
            Salir
          </button>
        </div>
      </div>
      {content}
    </Shell>
  );
}

function Shell({ children, error }) {
  return (
    <div className="min-h-screen w-full" style={{ background: C.bg, fontFamily: "ui-sans-serif, -apple-system, 'Segoe UI', sans-serif" }}>
      <div className="max-w-lg mx-auto px-4 py-6">
        {error && (
          <div className="mb-3 px-3 py-2 rounded-lg text-xs font-medium" style={{ background: C.parcialSoft, color: C.parcial }}>
            {error}
          </div>
        )}
        {children}
      </div>
    </div>
  );
}
